package org.kanger;
import java.util.*;
import org.kanger.ContextWitnessResultTransport.*;

/** Direct successor-barrier inventory replay; never calls its builder or merge adapter. */
final class ContextSignedWitnessSuccessorBarrierAudit {
 static final class Receipt {
  final ContextSignedWitnessSuccessorBarrier.Result result;
  private Receipt(ContextSignedWitnessSuccessorBarrier.Result result){this.result=result;}
 }
 private static void require(boolean b,String why){if(!b)throw new IllegalStateException(why);}
 static Receipt inspect(ContextSignedWitnessSuccessorBarrier.Result result,ContextSignedWitnessNextReceiver.Result next,ContextSignedWitnessContinuationScope.Receipt scope,int rows,ContextUniversalFrozenBranch.Limits limits,int auditWork,int capacity){
  require(result!=null&&result.merged&&result.next==next&&capacity>=1&&capacity<=4096,"Actual bounded successor-barrier result required");ContextSignedWitnessNextReceiver.check(next,scope,rows,limits,auditWork);require(next.status==ContextSignedWitnessNextReceiver.Status.CHECKED,"Unrefuted complete successor required");ConstraintBarrier prior=scope.current(),b=result.barrier;Runnable work=ContextGroundProductionRounds.budget(auditWork);
  require(b!=null&&b.merged&&b.branches.keySet().equals(next.checks.keySet())&&b.privatePools.keySet().equals(prior.privatePools.keySet()),"Different complete successor barrier inventory");List<Packet> shared=new ArrayList<>();shared.add(prior.packet);boolean localChanged=false;
  for(Map.Entry<Cut,ContextUniversalFrozenConstraints.Result> c:next.checks.entrySet()){work.run();ConstraintTransfer t=b.branches.get(c.getKey());require(t!=null&&t.proof==c.getValue()&&t.before==prior.packet&&t.privateBefore==prior.privatePools.get(c.getKey()),"Different actual successor product owner");ContextSignedWitnessNextReceiver.productOwner(next,c.getKey(),t);ContextUniversalSignedProductAudit.Result a=(next.localLimits==null?ContextUniversalSignedProductAudit.bind(c.getValue(),t,65536,auditWork):ContextUniversalSignedProductAudit.bindWithValidationReuse(c.getValue(),t,65536,auditWork,capacity).result);require(a.bound,a.reason);shared.add(t.output);boolean changed=!ContextWitnessResultTransport.sameContents(c.getValue().local,t.local,auditWork);require(t.localChanged==changed&&t.commonChanged==!ContextWitnessResultTransport.sameContents(prior.packet,t.output,auditWork),"Different actual successor transfer flags");localChanged|=changed;}
  ContextSignedWitnessInitialBarrierAudit.union(b.packet,shared,work,limits.factDepth);ContextWitnessResultTransport.family(b.packet,new ArrayList<>(next.checks.keySet()),limits.work);require(b.changed==!ContextWitnessResultTransport.sameContents(prior.packet,b.packet,auditWork)&&b.localChanged==localChanged,"Different successor-barrier proof-grade changes");
  for(Map.Entry<Cut,PrivatePool> p:prior.privatePools.entrySet()){work.run();PrivatePool old=p.getValue(),actual=b.privatePools.get(p.getKey());require(actual!=null&&actual.common==b.packet&&actual.signedSeeds==scope.seeds&&actual.x==old.x&&actual.snapshot==old.snapshot&&actual.cut.equals(old.cut)&&actual.sources.equals(old.sources)&&actual.declarations.size()==old.declarations.size(),"Different retained successor private scope");for(int i=0;i<old.declarations.size();++i){work.run();require(actual.declarations.get(i)==old.declarations.get(i),"Different original successor declaration");}ContextSignedWitnessInitialBarrierAudit.union(actual.local,Arrays.asList(b.packet,b.branches.get(p.getKey()).local),work,limits.factDepth);}
  require(result.units!=null&&result.compounds!=null&&result.units.prior!=null&&result.compounds.prior!=null&&result.units.barrier==b&&result.compounds.barrier==b&&result.units.common==b.packet&&result.compounds.common==b.packet&&result.units.checks.equals(next.checks)&&result.compounds.checks.equals(next.checks),"Different actual successor-barrier carrier owners");
  ContextUniversalSignedUnitExchange.Exchange units=result.units.prior;ContextUniversalCompoundExchange.Exchange compounds=result.compounds.prior;require(units.prior==null&&units.barrier==null&&compounds.prior==null&&compounds.barrier==null&&units.common==prior.packet&&compounds.common==prior.packet&&units.checks.equals(next.checks)&&compounds.checks.equals(next.checks),"Old/rebased carrier cannot stand in for fresh successor collection");require(compounds.maximumClauses==limits.clauses&&compounds.maximumAlternatives==limits.alternatives&&compounds.maximumDepth==limits.factDepth,"Different successor carrier policy");
  ContextUniversalSignedUnitExchange.check(result.units,scope.seeds.frame.plan.x,b.packet,limits.factDepth,work);ContextUniversalCompoundExchange.check(result.compounds,scope.seeds.frame.plan.x,b.packet,limits.factDepth,work);
  List<Cut> cuts=new ArrayList<>(next.checks.keySet());ContextUniversalSignedUnitExchange.Collection u=ContextUniversalSignedUnitExchange.collectWithValidationReuse(scope.seeds.frame.plan.x,prior.packet,cuts,next.checks,limits.clauses,limits.alternatives,limits.factDepth,limits.work,capacity).collection;ContextUniversalCompoundExchange.Collection c=ContextUniversalCompoundExchange.collectWithValidationReuse(scope.seeds.frame.plan.x,prior.packet,cuts,next.checks,limits.clauses,limits.alternatives,limits.factDepth,limits.work,capacity).collection;
  require(u.collected&&c.collected&&ContextUniversalSignedUnitExchange.sameContents(u.output,units,limits.work)&&ContextUniversalCompoundExchange.sameContents(c.output,compounds,limits.work),"Different independent successor carrier Source/depth inventory");return new Receipt(result);
 }
 static void check(Receipt receipt,ContextSignedWitnessNextReceiver.Result next,ContextSignedWitnessContinuationScope.Receipt scope,int rows,ContextUniversalFrozenBranch.Limits limits,int auditWork,int capacity){require(receipt!=null,"Actual successor-barrier receipt required");inspect(receipt.result,next,scope,rows,limits,auditWork,capacity);}
}
